{"connection_id":"BC-303c569a1085bc08b316","ref":"WLC:Ps.95.6","status":"accepted","reason":"The plural congregation is summoned to bow and kneel before its maker, giving bodily form to service.","paragraphs":[12],"evidence":["WLC:Ps.116.16","WLC:Ps.123.2","WLC:Ps.95.6"],"annotations":["S001-TEV-MTF-007"]}
