{"connection_id":null,"origin":"research","ref":"WLC:Ps.23.2","status":"accepted","reason":"Third-person verbs for the shepherd continue before the direct address of verse 4.","paragraphs":[12],"evidence":["WLC:Ps.23.1","WLC:Ps.23.2","WLC:Ps.23.3","WLC:Ps.23.4"],"annotations":["S001-TEV-MTF-006"]}
