{"connection_id":null,"origin":"research","ref":"WLC:Ps.8.7","status":"rejected","reason":"This is where rule and 'under his feet' occur before the livestock of verse 8, but Genesis 1:28 is the direct creation mandate already used.","paragraphs":[],"evidence":["WLC:Ps.8.7"],"annotations":[]}
{"connection_id":null,"origin":"research","ref":"WLC:Job.31.13","status":"accepted","reason":"Job's concern for the legal claim of his male and female slaves is the context for the shared-maker rationale in 31:15.","paragraphs":[14],"evidence":["WLC:Lev.25.42","WLC:Exod.21.2","WLC:Lev.25.43","WLC:Lev.25.46","WLC:Deut.5.14","WLC:Job.31.13","WLC:Job.31.15"],"annotations":["S001-TEV-MTF-011"]}
